import { Command } from 'commander';
import { spawnSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import os from 'os';

function runTask(cmd: string, args: string[]) {
  const result = spawnSync(cmd, args, { stdio: 'inherit' });
  if (result.status !== 0) throw new Error(`${cmd} ${args.join(' ')} failed`);
}

function installHook() {
  const hookDir = path.join(process.cwd(), '.git', 'hooks');
  if (!fs.existsSync(hookDir)) {
    console.error('No .git/hooks directory found. Are you in a git repo?');
    process.exit(1);
  }
  const isWindows = os.platform() === 'win32';
  const shHookPath = path.join(hookDir, 'pre-commit');
  const psHookPath = path.join(hookDir, 'pre-commit.ps1');

  const shScript = `#!/bin/sh\nnpm test\n`;
  fs.writeFileSync(shHookPath, shScript, { mode: 0o755 });

  const psScript = `#!/usr/bin/env pwsh\nnpm test\n`;
  fs.writeFileSync(psHookPath, psScript, { mode: 0o755 });

  console.log('Installed pre-commit hook that runs npm test.');
  if (isWindows) {
    console.log('Windows note: Git for Windows runs hooks via sh by default; PowerShell script is also written (pre-commit.ps1) if your hooksPath prefers it.');
  }
}

export function registerHooks(program: Command) {
  const hooks = program.command('hooks').description('Smart pre-commit tasks');

  hooks
    .command('run')
    .description('Run Prettier, ESLint, and tests')
    .action(() => {
      const tasks: Array<[string, string[]]> = [
        ['npx', ['prettier', '--check', '.']],
        ['npx', ['eslint', '.']],
        ['npm', ['test']]
      ];
      for (const [cmd, args] of tasks) {
        try {
          runTask(cmd, args);
        } catch (err) {
          console.error('Hook failed:', err);
          process.exit(1);
        }
      }
      console.log('All hooks passed.');
    });

  hooks
    .command('install')
    .description('Install git pre-commit hook to run tests')
    .option('--set-hooks-path', 'Configure core.hooksPath to .git/hooks if not already set')
    .action(async opts => {
      try {
        const current = spawnSync('git', ['config', 'core.hooksPath'], { encoding: 'utf8' }).stdout?.trim();
        if (current && current !== '.git/hooks') {
          console.warn(`Warning: core.hooksPath is set to ${current}. Hooks will be written to .git/hooks but git may use ${current}.`);
        }
      } catch (err) {
        console.warn('Could not read core.hooksPath:', err instanceof Error ? err.message : err);
      }
      installHook();
      if (opts.setHooksPath) {
        try {
          const result = spawnSync('git', ['config', 'core.hooksPath'], { encoding: 'utf8' });
          const current = result.stdout?.trim();
          if (!current) {
            spawnSync('git', ['config', 'core.hooksPath', '.git/hooks'], { stdio: 'inherit' });
            console.log('Configured core.hooksPath to .git/hooks');
          } else {
            console.log(`core.hooksPath already set to ${current}`);
          }
        } catch (err) {
          console.error('Could not set core.hooksPath:', err);
        }
      }
    });
}
